-- WAQT sample data. Safe to run repeatedly (upserts by unique keys).
-- Note: re-running updates catalogue details but does NOT reset stock_qty,
-- so real stock changes from orders are preserved.

INSERT INTO brands (name, slug, country_of_origin, founded_year, heritage_story, heritage_story_ar) VALUES
  ('Rolex', 'rolex', 'Switzerland', 1905, 'Founded in London in 1905 by Hans Wilsdorf and later established in Geneva, the house pioneered the waterproof Oyster case and the self-winding Perpetual rotor. From the summit of Everest to the depths of the Mariana Trench, its watches have accompanied explorers to the edges of the world — and become the definitive symbol of accomplishment across the Gulf.', 'تأسست في لندن عام ١٩٠٥ على يد هانز ويلسدورف ثم استقرت في جنيف، وكانت رائدة في ابتكار علبة أويستر المقاومة للماء ودوّار التعبئة الذاتية. من قمة إيفرست إلى أعماق خندق ماريانا، رافقت ساعاتها المستكشفين إلى أطراف العالم، وأصبحت الرمز الأسمى للإنجاز في الخليج.'),
  ('Patek Philippe', 'patek-philippe', 'Switzerland', 1839, 'The last family-owned independent Genevan manufacture, Patek Philippe has shaped the language of haute horlogerie since 1839. Its perpetual calendars, minute repeaters and the sculptural Nautilus are among the most coveted objects in collecting — heirlooms designed to be passed from one generation to the next.', 'آخر دار ساعات عائلية مستقلة في جنيف، شكّلت باتيك فيليب لغة الساعات الراقية منذ عام ١٨٣٩. تُعدّ تقاويمها الدائمة وساعاتها ذات الرنين وتصميم نوتيلوس النحتي من أكثر القطع المرغوبة لدى هواة الاقتناء — إرث يُورَّث من جيل إلى جيل.'),
  ('Audemars Piguet', 'audemars-piguet', 'Switzerland', 1875, 'Born in the Vallée de Joux in 1875 and still led by its founding families, Audemars Piguet shocked the world in 1972 with the Royal Oak — the first luxury sports watch in steel. Its octagonal bezel, eight hexagonal screws and hand-finished "Grande Tapisserie" dial remain an icon of bold design.', 'وُلدت في وادي جو عام ١٨٧٥ وما زالت تديرها العائلات المؤسسة، وقد أدهشت أوديمار بيغه العالم عام ١٩٧٢ بساعة رويال أوك — أول ساعة رياضية فاخرة من الفولاذ. وتبقى حافتها الثمانية وبراغيها السداسية الثمانية وقرصها المزخرف «غراند تابيسري» أيقونة للتصميم الجريء.'),
  ('Cartier', 'cartier', 'France', 1847, 'In 1904 Louis Cartier created one of the first modern wristwatches for the aviator Alberto Santos-Dumont. Since then the Parisian maison has defined elegance in form — the Tank, the Santos, the Panthère — uniting the precision of watchmaking with the artistry of high jewellery.', 'في عام ١٩٠٤ ابتكر لويس كارتييه واحدة من أولى ساعات اليد الحديثة للطيار ألبرتو سانتوس-دومون. ومنذ ذلك الحين رسمت الدار الباريسية معايير الأناقة في الشكل — تانك، سانتوس، بانتير — جامعةً بين دقة صناعة الساعات وفن المجوهرات الراقية.'),
  ('Omega', 'omega', 'Switzerland', 1848, 'From official Olympic timekeeper to the only watch flight-qualified by NASA for all crewed missions, Omega has spent more than 175 years at the frontier of precision. Its Master Chronometer movements, certified by METAS, resist magnetic fields beyond 15,000 gauss.', 'من الميقاتي الرسمي للألعاب الأولمبية إلى الساعة الوحيدة المعتمدة من ناسا لجميع المهمات المأهولة، أمضت أوميغا أكثر من ١٧٥ عاماً في طليعة الدقة. وتقاوم حركاتها «ماستر كرونوميتر» المعتمدة من METAS المجالات المغناطيسية التي تتجاوز ١٥٬٠٠٠ غاوس.')
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, country_of_origin = EXCLUDED.country_of_origin, founded_year = EXCLUDED.founded_year,
  heritage_story = EXCLUDED.heritage_story, heritage_story_ar = EXCLUDED.heritage_story_ar;

INSERT INTO watches (brand_id, model_name, collection, reference_number, price_aed, case_size_mm, material, movement,
  water_resistance_m, power_reserve_hours, gender, stock_qty, is_featured, image_url, description, description_ar,
  calibre, dial, material_detail, created_at) VALUES
  ((SELECT id FROM brands WHERE slug = 'rolex'), 'Submariner Date', 'Submariner', '126610LN', 52500, 41, 'Steel', 'Automatic', 300, 70, 'Men', 6, true, NULL, 'The reference diver’s watch since 1953. A unidirectional Cerachrom bezel, Chromalight display and the Oyster case, waterproof to 300 metres.', 'ساعة الغوص المرجعية منذ عام ١٩٥٣. حافة سيراكروم أحادية الاتجاه، وإضاءة كرومالايت، وعلبة أويستر مقاومة للماء حتى ٣٠٠ متر.', 'Calibre 3235', 'Black', 'Oystersteel', '2024-01-01T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'rolex'), 'GMT-Master II "Pepsi"', 'GMT-Master II', '126710BLRO', 69000, 40, 'Steel', 'Automatic', 100, 70, 'Men', 4, false, NULL, 'Born for intercontinental pilots, the two-tone red and blue bezel reads a second time zone at a glance — the companion of every Gulf traveller.', 'وُلدت لطياري الرحلات العابرة للقارات، وتقرأ حافتها الحمراء والزرقاء منطقة زمنية ثانية بلمحة — رفيقة كل مسافر خليجي.', 'Calibre 3285', 'Black', 'Oystersteel', '2025-02-02T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'rolex'), 'Cosmograph Daytona', 'Cosmograph Daytona', '126500LN', 148000, 40, 'Steel', 'Automatic', 100, 72, 'Men', 2, true, NULL, 'The chronograph of the racetrack. A black Cerachrom tachymetric bezel frames a white lacquer dial with contrasting black counters.', 'كرونوغراف حلبات السباق. حافة سيراكروم سوداء بمقياس سرعة تحيط بميناء أبيض لامع مع عدادات سوداء متباينة.', 'Calibre 4131', 'White', 'Oystersteel', '2025-03-03T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'rolex'), 'Day-Date 40', 'Day-Date', '228238', 168000, 40, 'Gold', 'Automatic', 100, 70, 'Men', 3, false, NULL, 'The “President” — crafted only in precious metals, displaying the day spelled out in full. The watch of heads of state.', '«الرئيس» — تُصنع من المعادن الثمينة فقط، وتعرض اسم اليوم كاملاً. ساعة رؤساء الدول.', 'Calibre 3255', 'Champagne', '18 ct Yellow Gold', '2023-04-04T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'rolex'), 'Lady-Datejust 28', 'Lady-Datejust', '279173', 58500, 28, 'Two-Tone', 'Automatic', 100, 55, 'Women', 5, false, NULL, 'Steel and yellow gold with a diamond-set mother-of-pearl dial and the iconic fluted bezel — timeless femininity.', 'فولاذ وذهب أصفر مع ميناء من عرق اللؤلؤ مرصّع بالألماس وحافة مضلّعة أيقونية — أنوثة خالدة.', 'Calibre 2236', 'Mother-of-pearl', 'Yellow Rolesor', '2024-05-05T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'patek-philippe'), 'Nautilus', 'Nautilus', '5811/1G-001', 625000, 41, 'Gold', 'Automatic', 120, 45, 'Men', 1, true, NULL, 'The successor to the legendary 5711, now in white gold with a blue gradated sunburst dial and the horizontally embossed pattern.', 'خليفة الأسطورة ٥٧١١، الآن من الذهب الأبيض مع ميناء أزرق متدرّج ونقش أفقي بارز.', 'Calibre 26-330 S C', 'Blue sunburst', '18 ct White Gold', '2025-06-06T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'patek-philippe'), 'Aquanaut', 'Aquanaut', '5167A-001', 212000, 40.8, 'Steel', 'Automatic', 120, 45, 'Men', 3, false, NULL, 'The casual-elegant Aquanaut with its “tropical” composite strap and embossed black dial — Patek Philippe at its most relaxed.', 'أكوانوت الأنيقة غير الرسمية بسوارها المركّب «الاستوائي» وميناء أسود بارز — باتيك فيليب بأكثر حالاتها استرخاءً.', 'Calibre 324 S C', 'Black embossed', 'Stainless Steel', '2023-07-07T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'patek-philippe'), 'Calatrava', 'Calatrava', '6119G-001', 138000, 39, 'Gold', 'Manual', 30, 65, 'Men', 4, false, NULL, 'The essence of the round dress watch, with a hobnail “Clous de Paris” bezel and a new hand-wound calibre.', 'جوهر ساعة السهرة المستديرة، بحافة «كلو دو باري» المزخرفة وعيار جديد يُعبّأ يدوياً.', 'Calibre 30-255 PS', 'Charcoal grey', '18 ct White Gold', '2024-08-08T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'patek-philippe'), 'Twenty~4 Automatic', 'Twenty~4', '7300/1200A-010', 112000, 36, 'Steel', 'Automatic', 30, 45, 'Women', 5, false, NULL, 'A round Twenty~4 for the modern woman: olive-green sunburst dial, diamond-set bezel and a fluid steel bracelet.', 'ساعة Twenty~4 مستديرة للمرأة العصرية: ميناء أخضر زيتوني مشع، وحافة مرصعة بالألماس، وسوار فولاذي انسيابي.', 'Calibre 324 S C', 'Olive green', 'Stainless Steel, Diamond Bezel', '2025-09-09T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'patek-philippe'), 'Perpetual Calendar Chronograph', 'Grand Complications', '5270P-014', 845000, 41, 'Platinum', 'Manual', 30, 65, 'Men', 2, false, NULL, 'Grand complication: a perpetual calendar chronograph in platinum with a salmon dial — one of the most coveted references in collecting.', 'تعقيد كبير: كرونوغراف بتقويم دائم من البلاتين مع ميناء بلون السلمون — من أكثر المراجع رغبة لدى الهواة.', 'Calibre CH 29-535 PS Q', 'Salmon', 'Platinum 950', '2024-10-10T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'audemars-piguet'), 'Royal Oak Selfwinding', 'Royal Oak', '15510ST.OO.1320ST.06', 185000, 41, 'Steel', 'Automatic', 50, 70, 'Men', 3, true, NULL, 'The modern Royal Oak: octagonal bezel, eight hexagonal screws and the “Grande Tapisserie” dial in deep blue.', 'رويال أوك العصرية: حافة ثمانية، وثمانية براغٍ سداسية، وميناء «غراند تابيسري» بالأزرق العميق.', 'Calibre 4302', 'Blue "Grande Tapisserie"', 'Stainless Steel', '2025-11-11T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'audemars-piguet'), 'Royal Oak "Jumbo" Extra-Thin', 'Royal Oak Jumbo', '16202ST.OO.1240ST.01', 430000, 39, 'Steel', 'Automatic', 50, 55, 'Men', 1, false, NULL, 'The 39 mm “Jumbo” Extra-Thin — the closest heir to Gérald Genta’s 1972 original, powered by the new calibre 7121.', '«جمبو» فائقة النحافة بقطر ٣٩ مم — أقرب وريث لتصميم جيرالد جنتا الأصلي عام ١٩٧٢، بعيار ٧١٢١ الجديد.', 'Calibre 7121', 'Bleu Nuit, Nuage 50', 'Stainless Steel', '2024-12-12T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'audemars-piguet'), 'Royal Oak Offshore Chronograph', 'Royal Oak Offshore', '26420SO.OO.A600CA.01', 164000, 43, 'Steel', 'Automatic', 100, 70, 'Men', 4, false, NULL, 'The bold Offshore chronograph with ceramic pushers, “Méga Tapisserie” dial and a quick-change rubber strap.', 'كرونوغراف أوفشور الجريء بأزرار سيراميكية، وميناء «ميغا تابيسري»، وسوار مطاطي سريع التبديل.', 'Calibre 4401', 'Black "Méga Tapisserie"', 'Stainless Steel & Ceramic', '2023-01-13T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'audemars-piguet'), 'Royal Oak Selfwinding 34', 'Royal Oak', '77450OR.ZZ.1361OR.01', 238000, 34, 'Rose Gold', 'Automatic', 50, 50, 'Women', 3, false, NULL, 'A 34 mm Royal Oak in pink gold with a diamond-set bezel — a jewel with a manufacture heart.', 'رويال أوك بقطر ٣٤ مم من الذهب الوردي بحافة مرصعة بالألماس — جوهرة بقلب مصنوع في الدار.', 'Calibre 5800', 'Pink gold-toned "Grande Tapisserie"', '18 ct Pink Gold, Diamond Bezel', '2025-02-14T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'audemars-piguet'), 'Royal Oak Perpetual Calendar', 'Perpetual Calendar', '26574PT.OO.1220PT.01', 690000, 41, 'Platinum', 'Automatic', 20, 40, 'Men', 2, false, NULL, 'A perpetual calendar that will not need correcting until 2100, in a platinum case and bracelet with an astronomical moon.', 'تقويم دائم لن يحتاج إلى تصحيح حتى عام ٢١٠٠، في علبة وسوار من البلاتين مع قمر فلكي.', 'Calibre 5134', 'Smoked blue', 'Platinum 950', '2024-03-15T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'cartier'), 'Santos de Cartier, Large', 'Santos', 'WSSA0018', 31200, 39.8, 'Steel', 'Automatic', 100, 42, 'Men', 7, true, NULL, 'The original pilot’s watch of 1904, reimagined with the QuickSwitch bracelet system and exposed screws.', 'ساعة الطيار الأصلية من عام ١٩٠٤ بتصميم جديد مع نظام QuickSwitch لتبديل السوار وبراغٍ ظاهرة.', 'Calibre 1847 MC', 'Silvered opaline', 'Stainless Steel', '2025-04-16T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'cartier'), 'Tank Louis Cartier, Large', 'Tank', 'WGTA0067', 48500, 33.7, 'Gold', 'Manual', 30, 38, 'Unisex', 4, false, NULL, 'The Tank Louis Cartier in yellow gold — the purest expression of the rectangle, worn by icons for a century.', 'تانك لويس كارتييه من الذهب الأصفر — أنقى تعبير عن المستطيل، ارتداها المشاهير لقرن كامل.', 'Calibre 1917 MC', 'Silvered beaded', '18 ct Yellow Gold', '2024-05-17T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'cartier'), 'Ballon Bleu de Cartier, 40 mm', 'Ballon Bleu', 'WSBB0040', 27300, 40, 'Steel', 'Automatic', 30, 42, 'Unisex', 8, false, NULL, 'A floating blue sapphire cabochon crown protected by an arch of steel — sculptural and effortlessly elegant.', 'تاج من الياقوت الأزرق يطفو تحميه قنطرة من الفولاذ — نحتية وأنيقة بلا تكلّف.', 'Calibre 1847 MC', 'Silvered guilloché', 'Stainless Steel', '2023-06-18T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'cartier'), 'Panthère de Cartier, Medium', 'Panthère', 'WGPN0009', 99500, 27, 'Gold', 'Quartz', 30, NULL, 'Women', 3, false, NULL, 'The supple Panthère bracelet flows like a second skin — Cartier’s jewellery heritage in its most iconic form.', 'سوار بانتير المرن ينساب كجلد ثانٍ — إرث كارتييه في المجوهرات بأكثر أشكاله شهرة.', 'Quartz Movement', 'Silvered', '18 ct Yellow Gold', '2025-07-19T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'cartier'), 'Santos-Dumont, Large', 'Santos', 'WGSA0032', 54000, 43.5, 'Rose Gold', 'Manual', 30, 36, 'Men', 2, false, NULL, 'The slender Santos-Dumont in rose gold, faithful to the 1904 design made for the Brazilian aviator.', 'سانتوس-دومون النحيفة من الذهب الوردي، وفيّة لتصميم عام ١٩٠٤ الذي صُنع للطيار البرازيلي.', 'Calibre 430 MC', 'Silvered', '18 ct Rose Gold', '2024-08-20T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'omega'), 'Speedmaster Moonwatch Professional', 'Speedmaster', '310.30.42.50.01.001', 29200, 42, 'Steel', 'Manual', 50, 50, 'Men', 6, true, NULL, 'The Moonwatch — flight-qualified by NASA and worn on the Moon in 1969, now with the Master Chronometer calibre 3861.', 'ساعة القمر — معتمدة من ناسا ورُفعت على سطح القمر عام ١٩٦٩، الآن بعيار ماستر كرونوميتر ٣٨٦١.', 'Co-Axial Master Chronometer 3861', 'Black step dial', 'Stainless Steel', '2025-09-21T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'omega'), 'Seamaster Diver 300M', 'Seamaster', '210.30.42.20.03.001', 23100, 42, 'Steel', 'Automatic', 300, 55, 'Men', 7, false, NULL, 'The diver of choice for a famous secret agent: laser-engraved ceramic wave dial and a helium escape valve.', 'ساعة الغوص المفضلة لعميل سري شهير: ميناء سيراميكي بنقش الأمواج بالليزر وصمام لتسريب الهيليوم.', 'Co-Axial Master Chronometer 8800', 'Blue ceramic waves', 'Stainless Steel', '2024-10-22T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'omega'), 'Seamaster Aqua Terra 150M', 'Aqua Terra', '220.10.41.21.03.004', 25900, 41, 'Steel', 'Automatic', 150, 60, 'Men', 6, false, NULL, 'Inspired by the teak decks of luxury sailing yachts — a versatile everyday companion, anti-magnetic to 15,000 gauss.', 'مستوحاة من أسطح خشب الساج في اليخوت الفاخرة — رفيقة يومية متعددة الاستخدامات، مقاومة للمغناطيس حتى ١٥٬٠٠٠ غاوس.', 'Co-Axial Master Chronometer 8900', 'Blue teak', 'Stainless Steel', '2025-11-23T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'omega'), 'Constellation 29 mm', 'Constellation', '131.20.29.20.55.002', 34800, 29, 'Two-Tone', 'Automatic', 50, 50, 'Women', 5, false, NULL, 'The signature “claws” and half-bracelet in steel and Sedna™ gold frame a diamond-set mother-of-pearl dial.', '«المخالب» المميزة ونصف السوار من الفولاذ وذهب سيدنا™ تحيط بميناء من عرق اللؤلؤ مرصّع بالألماس.', 'Co-Axial Master Chronometer 8700', 'White mother-of-pearl', 'Steel & 18K Sedna™ Gold', '2024-12-24T10:00:00Z'),
  ((SELECT id FROM brands WHERE slug = 'omega'), 'Speedmaster Moonwatch Moonshine™ Gold', 'Speedmaster', '310.60.42.50.99.001', 152000, 42, 'Gold', 'Manual', 50, 50, 'Men', 2, false, NULL, 'The Moonwatch in Omega’s proprietary Moonshine™ gold with a green dial — a paler, more fade-resistant yellow gold.', 'ساعة القمر من ذهب مونشاين™ الخاص بأوميغا مع ميناء أخضر — ذهب أصفر أفتح لوناً وأكثر مقاومة للبهتان.', 'Co-Axial Master Chronometer 3861', 'Green PVD', '18K Moonshine™ Gold', '2025-01-25T10:00:00Z')
ON CONFLICT (reference_number) DO UPDATE SET
  brand_id = EXCLUDED.brand_id, model_name = EXCLUDED.model_name, collection = EXCLUDED.collection,
  price_aed = EXCLUDED.price_aed, case_size_mm = EXCLUDED.case_size_mm, material = EXCLUDED.material,
  movement = EXCLUDED.movement, water_resistance_m = EXCLUDED.water_resistance_m,
  power_reserve_hours = EXCLUDED.power_reserve_hours, gender = EXCLUDED.gender, is_featured = EXCLUDED.is_featured,
  description = EXCLUDED.description, description_ar = EXCLUDED.description_ar, calibre = EXCLUDED.calibre,
  dial = EXCLUDED.dial, material_detail = EXCLUDED.material_detail, created_at = EXCLUDED.created_at;

